{
  "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
  "contentVersion": "1.0.0.0",
  "parameters": {
    "environment": { "type": "string", "defaultValue": "lab", "allowedValues": ["lab", "test"] },
    "location": { "type": "string", "defaultValue": "[resourceGroup().location]" },
    "subnetPrefix": { "type": "string", "defaultValue": "10.60.1.0/24" }
  },
  "variables": {
    "networkName": "[concat('school-', parameters('environment'), '-vnet')]",
    "nsgName": "[concat('school-', parameters('environment'), '-nsg')]",
    "resourceTags": { "project": "classroom" }
  },
  "resources": [
    {
      "type": "Microsoft.Network/networkSecurityGroups",
      "apiVersion": "2025-01-01",
      "name": "[variables('nsgName')]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "properties": { "securityRules": [] }
    },
    {
      "type": "Microsoft.Network/virtualNetworks",
      "apiVersion": "2025-01-01",
      "name": "[variables('networkName')]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "properties": {
        "addressSpace": { "addressPrefixes": ["10.60.0.0/16"] }
      }
    },
    {
      "type": "Microsoft.Network/virtualNetworks/subnets",
      "apiVersion": "2025-01-01",
      "name": "[concat(variables('networkName'), '/web')]",
      "dependsOn": [
        "[resourceId('Microsoft.Network/virtualNetworks', variables('networkName'))]",
        "[resourceId('Microsoft.Network/networkSecurityGroups', variables('nsgName'))]"
      ],
      "properties": {
        "addressPrefix": "[parameters('subnetPrefix')]",
        "networkSecurityGroup": {
          "id": "[resourceId('Microsoft.Network/networkSecurityGroups', variables('nsgName'))]"
        }
      }
    }
  ],
  "outputs": {
    "networkId": {
      "type": "string",
      "value": "[resourceId('Microsoft.Network/virtualNetworks', variables('networkName'))]"
    }
  }
}

targetScope = 'resourceGroup'

@allowed(['lab', 'test'])
param environment string = 'lab'
param location string = resourceGroup().location
param subnetPrefix string = '10.60.1.0/24'

var networkName = 'school-${environment}-vnet'
var nsgName = 'school-${environment}-nsg'
var resourceTags = {
  project: 'classroom'
}

resource schoolNsg 'Microsoft.Network/networkSecurityGroups@2025-01-01' = {
  name: nsgName
  location: location
  tags: resourceTags
  properties: {
    securityRules: []
  }
}

resource schoolNetwork 'Microsoft.Network/virtualNetworks@2025-01-01' = {
  name: networkName
  location: location
  tags: resourceTags
  properties: {
    addressSpace: {
      addressPrefixes: ['10.60.0.0/16']
    }
  }
}

resource schoolSubnet 'Microsoft.Network/virtualNetworks/subnets@2025-01-01' = {
  parent: schoolNetwork
  name: 'web'
  properties: {
    addressPrefix: subnetPrefix
    networkSecurityGroup: {
      id: schoolNsg.id
    }
  }
}

output networkId string = schoolNetwork.id

param subnetPrefix string = '10.60.1.0/26'

var resourceTags = {
  project: 'classroom'
  costCenter: 'school-lab'
}
